import { useState } from 'react';
import type { ConverterType } from '../types';
import { formatDecimal } from '../utils/format';

interface UnitMap {
  [key: string]: string[];
}

export const useConverter = () => {
  const [converterType, setConverterType] = useState<ConverterType>('length');
  const [convertValue, setConvertValue] = useState('');
  const [fromUnit, setFromUnit] = useState('meters');
  const [toUnit, setToUnit] = useState('kilometers');
  const [convertResult, setConvertResult] = useState<string | null>(null);
  const [unitRate, setUnitRate] = useState<string | null>(null);

  const lengthUnits = [
    'meters',
    'kilometers',
    'centimeters',
    'millimeters',
    'miles',
    'yards',
    'feet',
    'inches',
    'astronomicalUnit',
    'lightYear',
  ];
  const weightUnits = ['kilograms', 'grams', 'pounds', 'ounces', 'tonnes'];
  const timeUnits = [
    'milliseconds',
    'seconds',
    'minutes',
    'hours',
    'days',
    'weeks',
    'months',
    'years',
  ];
  const temperatureUnits = ['celsius', 'fahrenheit', 'kelvin'];
  const speedUnits = ['ms', 'kmh', 'mph', 'knots', 'mpm'];
  const areaUnits = [
    'm2',
    'km2',
    'hectares',
    'acres',
    'ft2',
    'in2',
    'mi2',
    'au2',
    'ly2',
  ];
  const volumeUnits = [
    'liters',
    'milliliters',
    'gallons',
    'quarts',
    'pints',
    'm3',
    'cm3',
    'km3',
    'in3',
    'ft3',
    'mi3',
    'au3',
    'ly3',
  ];
  const dataUnits = [
    'bits',
    'bytes',
    'kilobytes',
    'megabytes',
    'gigabytes',
    'terabytes',
    'petabytes',
    'exabytes',
    'zettabytes',
  ];

  const units: UnitMap = {
    length: lengthUnits,
    weight: weightUnits,
    time: timeUnits,
    temperature: temperatureUnits,
    speed: speedUnits,
    area: areaUnits,
    volume: volumeUnits,
    data: dataUnits,
  };

  const conversionRates: Record<string, number> = {
    meters: 1,
    kilometers: 1000,
    centimeters: 0.01,
    millimeters: 0.001,
    miles: 1609.34,
    yards: 0.9144,
    feet: 0.3048,
    inches: 0.0254,
    astronomicalUnit: 149597870700,
    lightYear: 9460730472580800,
    kilograms: 1,
    grams: 0.001,
    pounds: 0.453592,
    ounces: 0.0283495,
    tonnes: 1000,
    milliseconds: 0.001,
    seconds: 1,
    minutes: 60,
    hours: 3600,
    days: 86400,
    weeks: 604800,
    months: 2628000,
    years: 31536000,
    ms: 1,
    kmh: 0.277778,
    mph: 0.44704,
    knots: 0.514444,
    mpm: 0.016667,
    m2: 1,
    km2: 1000000,
    hectares: 10000,
    acres: 4046.86,
    ft2: 0.092903,
    in2: 0.00064516,
    mi2: 2589988.11,
    au2: 2.23795229157e22,
    ly2: 8.95054210748e31,
    liters: 1,
    milliliters: 0.001,
    gallons: 3.78541,
    quarts: 0.946353,
    pints: 0.473176,
    m3: 1000,
    cm3: 0.001,
    km3: 1e12,
    in3: 0.0163871,
    ft3: 28.3168,
    mi3: 4168181825.44,
    au3: 3.34792899409e33,
    ly3: 8.46628021441e50,
    bits: 0.125,
    bytes: 1,
    kilobytes: 1024,
    megabytes: 1048576,
    gigabytes: 1073741824,
    terabytes: 1099511627776,
    petabytes: 1125899906842624,
    exabytes: 1152921504606846976,
    zettabytes: 1180591620717411303424,
  };

  const conversionTemperature = (
    value: number,
    from: string,
    to: string,
  ): number => {
    let celsius: number;
    if (from === 'celsius') celsius = value;
    else if (from === 'fahrenheit') celsius = ((value - 32) * 5) / 9;
    else if (from === 'kelvin') celsius = value - 273.15;
    else celsius = value;

    if (to === 'celsius') return celsius;
    else if (to === 'fahrenheit') return (celsius * 9) / 5 + 32;
    else if (to === 'kelvin') return celsius + 273.15;
    return celsius;
  };

  const convertUnits = () => {
    if (!convertValue || !fromUnit || !toUnit) return;
    const value = parseFloat(convertValue);
    let result: number;
    let rateValue = 0;

    if (converterType === 'temperature') {
      result = conversionTemperature(value, fromUnit, toUnit);
      rateValue = conversionTemperature(1, fromUnit, toUnit);
    } else {
      const fromRate = conversionRates[fromUnit];
      const toRate = conversionRates[toUnit];
      if (fromRate && toRate) {
        const baseValue = value * fromRate;
        result = baseValue / toRate;
        rateValue = fromRate / toRate;
      } else {
        return;
      }
    }

    // Format with the shared smart decimal formatting
    setConvertResult(formatDecimal(result));
    setUnitRate(formatDecimal(rateValue));
  };

  const handleConverterTypeChange = (newType: ConverterType) => {
    setConverterType(newType);
    setConvertValue('');
    setConvertResult(null);
    setUnitRate(null);

    const defaults: Record<ConverterType, { from: string; to: string }> = {
      length: { from: 'meters', to: 'kilometers' },
      weight: { from: 'kilograms', to: 'pounds' },
      time: { from: 'hours', to: 'minutes' },
      temperature: { from: 'celsius', to: 'fahrenheit' },
      speed: { from: 'kmh', to: 'mph' },
      area: { from: 'hectares', to: 'acres' },
      volume: { from: 'liters', to: 'gallons' },
      data: { from: 'megabytes', to: 'gigabytes' },
    };

    setFromUnit(defaults[newType].from);
    setToUnit(defaults[newType].to);
  };

  const setFromUnitClear = (unit: string) => {
    setFromUnit(unit);
    setConvertResult(null);
    setUnitRate(null);
  };

  const setToUnitClear = (unit: string) => {
    setToUnit(unit);
    setConvertResult(null);
    setUnitRate(null);
  };

  const setConvertValueClear = (value: string) => {
    setConvertValue(value);
    setConvertResult(null);
    setUnitRate(null);
  };

  return {
    converterType,
    convertValue,
    fromUnit,
    toUnit,
    convertResult,
    unitRate,
    units,
    setConvertValue: setConvertValueClear,
    setFromUnit: setFromUnitClear,
    setToUnit: setToUnitClear,
    convertUnits,
    handleConverterTypeChange,
  };
};
